  return (
    <article aria-label={name} title={title}>
      <h2>{label(name)}</h2>
      <p>EUR {price.toFixed(2)}</p>
      {onOrder && <button type="button" disabled={soldOut} onClick={() => onOrder(name)}>Add {name}</button>}
    </article>
  )
}

